// TH14 v1.00b st05mbs.ecl: MBoss(10-39) entry preamble + MBoss1(54-90) entry,
// dependency MBoss1_at(92-133). Segment timer starts at MBoss1 timerReset (source T=0).
const TIME_LIMIT: int = 2194;
const OPENING_BUFFER: int = 120;
const SKIP_OPENING: int = 40;
const SKIP_OPENING2: int = 30;

const TH14_RICE: int = 480;          // source SETSPRITE type 8
const TH14_INVERT_RICE: int = 592;   // source etSprite/SETSPRITE type 15

// MBoss1_at EX chain, async=0 in source order:
//   ANIM(1) birth animation omitted by policy;
//   VELTIME 30 frames 2.0 -> 1.0 (s=-999999 = keep current bullet angle);
//   SETSPRITE 8/2; VELTIME 40 1.0 -> 3.0; SETSPRITE 15/2; VELTIME 60 3.0 -> 0.4.
xformdef MB1_EX {
    step_speed(1.0fx, 30);
    wait(30);
    set_sprite(TH14_RICE, 2);
    step_speed(3.0fx, 40);
    wait(40);
    set_sprite(TH14_INVERT_RICE, 2);
    step_speed(0.4fx, 60);
}

// moveRand(60,4,1.0) + moveLimit(0,128,280,64): x in [-140,140], y in [96,160].
// Direction inner zone is center +/- width/4: x +/-70, y 112..144.
// self_int(0) = step count, self_fx(0/1) = cos/sin. This card owns those slots.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    // Source 412: signed unit random * pi, unwrapped BAM, then fabs/y fix, then +/-pi/2 guard.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// Source clock lives in self_int(1); every wait is cut at the native 1500-frame interrupt.
sub time_wait(frames: int) {
    var left: int = 1500 - self_int(1);
    var n: int = frames;
    if left < n { n = left; }
    if n < 0 { n = 0; }
    card_wait(n);
    set_self_int(1, self_int(1) + n);
}

async sub mb1_boss() {
    set_invuln(65535);
    set_hurtbox(24fx);   // source setHurtbox(48,48): circular radius = width/2
    set_hitbox(24fx);    // source setHitbox(48,48)
    // MBoss entry: spawn is already at movePosTime destination (0,128); keep the two
    // explicit waits (dialogWait omitted). moveLimit is enforced by arm_next_step.
    wait(SKIP_OPENING);
    wait(SKIP_OPENING2);

    // MBoss1 timerReset / setInterrupt(0,2200,1500,"MBossCard1"):
    // phase hp_threshold/time_limit live in control; this loop stops at the native 1500.
    var rank: int = global(GVAR_RANK);
    var nways: int = 16;
    var tail_wait: int = 60;
    if rank == 1 { nways = 28; }
    if rank == 2 { nways = 32; tail_wait = 30; }
    if rank >= 3 { nways = 36; tail_wait = 10; }

    var f0: angle = 419bam;   // source F0 = 0.040143 rad
    var i0: int = 10;
    var stop_now: int = 0;
    set_self_int(1, 0);
    while self_int(1) < 1500 {
        time_wait(60);
        if self_int(1) >= 1500 { break; }

        // MBoss1_at: etNew/etAim(3)/etSprite(15,2)/etCount/etAngle/etSpeed + EX.
        sh_reset(0);
        sh_sprite(0, TH14_INVERT_RICE, 2);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, nways, 1);
        sh_speed(0, 2fx, 0fx);
        sh_xform(0, MB1_EX);

        var base: angle = rand(65536) as angle;   // source %RANDRAD, full circle
        var d: fx = 96fx;                        // source %B
        for j in 0..i0 {
            if self_int(1) >= 1500 { stop_now = 1; break; }
            sh_angle(0, base, 0bam);
            sh_dist(0, d - 8fx);   // etDist(%B) plus ANIM birth retreat 4 * 2.0
            sh_fire(0);
            time_wait(3);
            base = base + f0;
            d = d - 8fx;
        }
        if stop_now != 0 { break; }

        time_wait(10);
        if self_int(1) >= 1500 { break; }
        time_wait(60);
        if self_int(1) >= 1500 { break; }
        f0 = 0bam - f0;                 // source %F0 = %F0 * -1
        time_wait(tail_wait);
        if self_int(1) >= 1500 { break; }
        move_rand();
        i0 = i0 + 1;
    }

    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);   // native timeout stops movement
    loop { wait(60); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13200, 0, 0, 0, mb1_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
